	const PxVec3 inertiaTensor = PxVec3(ii.x == 0.f ? 0.f : (1.f / ii.x), ii.y == 0.f ? 0.f : (1.f / ii.y), ii.z == 0.f ? 0.f : (1.f / ii.z));
	const PxReal invMass = bodyCore.inverseMass;
	const PxReal m = invMass == 0.f ? 0.f : 1.0f / invMass;

